"""Share of the total nights per booking."""
from bookings import load_bookings


def nights_shares(bookings):
    """Return each booking's share of the total nights, in order."""
    total = sum(x.nights for x in bookings)
    return [x.nights / total for x in bookings]


def stored_shares():
    """Shares for the stored bookings."""
    return nights_shares(load_bookings())


def top_share(bookings):
    """Return the largest share, or 0.0 when there are no bookings."""
    shares = nights_shares(bookings)
    return max(shares) if shares else 0.0
